mapper.select:
SELECT h.id,h.name,h.city,h.address,h.price,h.original_price,h.facilities,h.stars,
       h.overall_rating,h.review_count,h.longitude,h.latitude,
       (SELECT hi.image FROM hotel_image hi WHERE hi.hotel_id = h.id
        ORDER BY hi.sort_order LIMIT 1) AS mainImage
       ,  AS cursorSortValue
FROM hotel h

    AND h.stars = #{stars}
    AND h.city = #{city}
    AND h.price >= #{minPrice}
    AND h.price <= #{maxPrice}


        AND (

             FIND_IN_SET(#{facility}, h.facilities) > 0

        )




                AND (h.price > #{lastValue}
                OR (h.price = #{lastValue} AND h.id > #{lastId}))


                AND (h.price < #{lastValue}
                OR (h.price = #{lastValue} AND h.id < #{lastId}))


                AND (COALESCE(, 1000000000000000) > #{lastValue}
                OR (COALESCE(, 1000000000000000) = #{lastValue} AND h.id > #{lastId}))



                    AND h.overall_rating IS NULL AND h.id > #{lastId}

                        AND (h.overall_rating < #{lastValue} OR h.overall_rating IS NULL
                        OR (h.overall_rating = #{lastValue} AND h.id > #{lastId}))








    ORDER BY h.price ASC, h.id ASC
    ORDER BY h.price DESC, h.id DESC

        ORDER BY COALESCE(, 1000000000000000) ASC, h.id ASC


    ORDER BY h.overall_rating DESC, h.id ASC

LIMIT #{size}

mapper.update:
UPDATE hotel
SET
    overall_rating = #{newAvgScore},
    review_count = #{newCommentCount}
WHERE id = #{hotelId}

mapper.select:
SELECT id,name,price,image,overall_rating AS rating
FROM hotel LEFT JOIN hotel_image AS hi ON hotel.id = hi.hotel_id AND hi.sort_order = 1
WHERE id = #{id}
